SET ThousandSep=',';
SET DecimalSep='.';
SET MoneyFormat='$#,##0.00';
SET DateFormat='MM/DD/YYYY';
SET TimeFormat='hh:mm:ss';

// ========== Section Access (RLS) ==========
Section Access;
LOAD * INLINE [
  ACCESS, USERID, REGION
  USER, admin@company.com, *
  USER, east_mgr@company.com, East
  USER, west_mgr@company.com, West
  USER, central_mgr@company.com, Central
  USER, south_mgr@company.com, South
];
Section Application;

// ========== Calendar Table ==========
Calendar:
LOAD
  Date,
  Year(Date) as Year,
  Month(Date) as Month,
  Day(Date) as Day,
  WeekDay(Date) as DayOfWeek,
  'Q' & Ceil(Month(Date)/3) as Quarter,
  Year(Date) & '-' & Num(Month(Date), '00') as YearMonth
;
LOAD
  Date(MakeDate(2020) + IterNo() - 1) as Date
AUTOGENERATE 2192;

// ========== Sales ==========
Sales:
LOAD
  OrderID, OrderDate, CustomerID, ProductID, SalesRepID,
  Quantity, UnitPrice, Discount, Amount, Cost,
  ShipDate, ShipMode, Region
FROM [data/Sales.csv] (txt, codepage is 1252, embedded labels, delimiter is ',');

// ========== Customers ==========
Customers:
LOAD
  CustomerID, CustomerName, Segment, Country, State, City, PostalCode, Phone, Email
FROM [data/Customers.xlsx] (ooxml, embedded labels, table is Customers);

// ========== Products ==========
Products:
SQL SELECT ProductID, ProductName, Category, SubCategory, Brand, UnitCost, ListPrice
FROM ProductCatalog.dbo.Products;

// ========== Sales Reps ==========
SalesReps:
LOAD SalesRepID, SalesRepName, Team, HireDate, ManagerName
FROM [data/SalesReps.csv] (txt, codepage is 1252, embedded labels, delimiter is ',');

// ========== Targets ==========
Targets:
LOAD Year, Month, Region, TargetAmount, TargetQuantity
FROM [data/Targets.xlsx] (ooxml, embedded labels, table is Targets);

// ========== Returns ==========
Returns:
LOAD ReturnID, OrderID, ReturnDate, ReturnReason, RefundAmount
FROM [data/Returns.csv] (txt, codepage is 1252, embedded labels, delimiter is ',');

// ========== Mapping Table for Ship Mode ==========
ShipModeMap:
MAPPING LOAD * INLINE [
  QlikMode, PBIMode
  First Class, Priority
  Second Class, Standard
  Same Day, Express
  Standard Class, Economy
];

// Apply mapping
LET vShipMapped = ApplyMap('ShipModeMap', ShipMode, 'Unknown');
